#include <iostream>
#include <string>
#include <iterator>
#include <list>
int main() {
  std::string str = "Hello, world!";
  std::string::iterator it = str.begin() + 7;
  *it = 'W';
  std::cout << str << std::endl;
  std::list<char> charList = {'H', 'e', 'l', 'l', 'o'};
  auto it2 = charList.begin();
  std::advance(it2,0);
  *it2 = 'J';
  for(char c: charList) std::cout << c;
  std::cout << std::endl;
  return 0;
}
